pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IOracleProviderMinimal {
    struct OracleVersion { uint256 version; uint256 timestamp; int256 price; }
    function currentVersion() external view returns (OracleVersion memory);
    function sync() external returns (OracleVersion memory);
}

// A minimal oracle whose price we can set via a public setter; acts as an external oracle
contract SimpleOracle is IOracleProviderMinimal {
    OracleVersion public _v;
    function set(int256 price, uint256 version, uint256 ts) public {
        _v.price = price;
        _v.version = version;
        _v.timestamp = ts;
    }
    function currentVersion() external view returns (OracleVersion memory) { return _v; }
    function sync() external returns (OracleVersion memory) { return _v; }
}

contract InvMutTest is Test {
    C c;
    SimpleOracle oracle;

    function setUp() public {
        c = new C();
        oracle = new SimpleOracle();
    }

    // fuzz the oracle price (int256) and version to find a case where transformed price != raw price
    function testFuzz_property(int256 oraclePrice, uint256 oracleVersion) public {
        // keep wide bounds but avoid trivial zero-version bootstrap cases if any (we allow version 0 too)
        // deploy and set oracle to controlled address via updateOracle which requires onlyProductOwner in real flows;
        // here we only need to inspect currentVersion getter, so we can cheat by using storage directly if needed,
        // but contract C exposes updateOracle only to product owner; instead we will rely on the fact that
        // __UPayoffProvider__initialize was called in initialize; however test must not call initialize (it would revert);
        // workaround: We only need to observe c.currentVersion(); it calls oracle() stored address — we cannot set that from here.
        // To make this test valid without calling initialize, we instead will call c.currentVersion() in a try/catch
        // and compare to oracle.currentVersion() via our deployed SimpleOracle after forcing c's oracle storage by
        // deploying a new C and then using low-level call to set its oracle storage is disallowed. Instead, we can
