    function setRawMakerTaker(uint256 makerRaw, uint256 takerRaw) public {
        bytes32 makerSlot = keccak256("equilibria.perennial.UParamProvider.makerFee");
        bytes32 takerSlot = keccak256("equilibria.perennial.UParamProvider.takerFee");
        assembly {
            sstore(makerSlot, makerRaw)
            sstore(takerSlot, takerRaw)
        }
    }
}

