// Note: many types and functions are thin stubs above to allow this test file to compile and focus the property assertion.

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the stored taker fee by calling initializer path which sets it; we must supply a ProductInfo
    // that routes through initialize to set takerFee. We'll fuzz the maker of the product's takerFee value
    // by providing a uint256 rawFee which we convert to UFixed18 via UFixed18Lib.ONE * raw / scaling.
    // Here we only need some fuzzed uint256 to be used as the stored taker fee when initializing.

    // We cannot import UFixed18 types here; instead, we will rely on the fact that the public getter
    // takerFee() returns the stored value we initialized via __UParamProvider__initialize which expects
    // a UFixed18 typed argument. To construct such a value in tests we can call into the contract's
    // external initialize which accepts a ProductInfo struct. However importing all types is heavy.
    // Simpler approach: call c.updateTakerFee after deploying and initializing controller ownership path
    // is needed. But the contract requires initialize to be called by controller (msg.sender) in setUp.
    // To avoid heavy scaffolding, we instead use low-level storage write to the taker fee slot via
    // direct call is not allowed by rules. Therefore we craft a ProductInfo minimal ABI to call initialize.

    // To keep this test focused and minimal: we will fuzz an address to act as controller and simulate
    // calling initialize via that address. The contract's initialize expects msg.sender to be IController
    // and will call __UControllerProvider__initialize(IController(msg.sender)) which requires
    // Address.isContract(address(controller_)) -> controller must be a contract. We'll deploy a tiny
    // mock controller that forwards owner/coordinator calls and allows initialization. That helper is
    // internal and deterministic; the fuzzed input will be the raw uint256 fee we place into ProductInfo.takerFee.

    // The fuzzer parameter is uint256 rawTaker; the test will construct a UFixed18-like value by packing
    // it into the ProductInfo and calling initialize; then read takerFee() and assert it equals the stored value.

    function testFuzz_property(uint256 rawTaker) public {
        // keep a wide domain but avoid overflow in construction: bound rawTaker to 1e30 to be safe
        uint256 bounded = bound(rawTaker, 0, 1e30);

        // deploy a minimal controller contract that reports required values and acts as msg.sender for initialize
        MinimalController controller = new MinimalController(address(this));

        // build a ProductInfo in calldata via ABI-encoding and call initialize on c with controller as msg.sender
        // We need to craft the ProductInfo struct fields. To avoid importing complex types, use abi.encode with
        // the exact layout expected by C.initialize(ProductInfo).
        // ProductInfo fields (in order): string name; string symbol; PayoffDefinition payoffDefinition; IOracleProvider oracle;
        // UFixed18 maintenance; UFixed18 fundingFee; UFixed18 makerFee; UFixed18 takerFee; UFixed18 positionFee; UFixed18 makerLimit;
        // JumpRateUtilizationCurve utilizationCurve;
        // Many of these are complex; instead we'll bypass initialize and directly store the taker fee into storage slot
        // via c.updateTakerFee which is external and requires only onlyProductOwner & settleProduct; complex as well.

        // Simpler: call initialize with minimal dummy data by using a contract that acts as controller and provides
        // the expected owner and product creation logic. We'll create DummyProductInfoProvider that returns ABI-packed
        // calldata; but constructing all nested structs is cumbersome in solidity test. To keep within constraints,
        // we take an alternate approach: the property we assert can be observed by directly calling takerFee() after
        // writing to its storage slot via a benign call path: the UFixed18Storage slot key is keccak256("equilibria.perennial.UParamProvider.takerFee").
        // We cannot use vm.store (forbidden). Therefore, instead we will rely on initialize being callable by any contract
        // with a simple ProductInfo formed in Solidity using the contract types by importing C; since C's ProductInfo type
        // is declared in the imported C, we can construct it here. We'll create helper mock objects for types used: IOracleProvider and PayoffDefinition.

        // Deploy a trivial oracle provider and payoffDefinition substitute
        SimpleOracle oracle = new SimpleOracle();
        // Build PayoffDefinition (its type is declared in the imported C). We'll create bytes30 zero filled.
        C.ProductInfo memory info;
        info.name = "T";
        info.symbol = "T";
        info.payoffDefinition = C.PayoffDefinition(C.PayoffDefinitionLib.PayoffType(0), C.PayoffDefinitionLib.PayoffDirection(0), bytes30(0));
        info.oracle = IOracleProvider(address(oracle));

        // Create UFixed18 via multiplying by 1e18: we cannot construct UFixed18 directly here because type alias is in C.
        // But we can cast from uint256 using the underlying type since UFixed18 is a type alias for uint256 in the imported C context.
        uint256 scaled = bounded * 1e18;
        info.maintenance = UFixed18.wrap(0);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(scaled);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(1e36);
        info.utilizationCurve = JumpRateUtilizationCurve({minRate: PackedFixed18.wrap(0), maxRate: PackedFixed18.wrap(0), targetRate: PackedFixed18.wrap(0), targetUtilization: PackedUFixed18.wrap(0)});

        // initialize must be called with msg.sender == controller; use vm.prank
        vm.prank(address(controller));
        c.initialize(info);

        // Now read the takerFee via public getter
        UFixed18 got = c.takerFee();

        // The general rule: the getter returns exactly the stored taker fee that we initialized. We assert equality
        // Compare against the scaled value we set
        assertTrue(UFixed18.unwrap(got) == scaled);
    }
}

// Minimal helper contracts and type aliases used in the test. These mirror the types used by C but are kept minimal.
interface IOracleProvider {
    struct OracleVersion { uint256 version; uint256 timestamp; int256 price; }
    function sync() external returns (OracleVersion memory);
    function currentVersion() external view returns (OracleVersion memory);
    function atVersion(uint256 oracleVersion) external view returns (OracleVersion memory);
}

contract SimpleOracle is IOracleProvider {
    function sync() external pure returns (OracleVersion memory) { return OracleVersion({version: 1, timestamp: block.timestamp, price: 0}); }
    function currentVersion() external pure returns (OracleVersion memory) { return OracleVersion({version: 1, timestamp: block.timestamp, price: 0}); }
    function atVersion(uint256) external pure returns (OracleVersion memory) { return OracleVersion({version: 1, timestamp: block.timestamp, price: 0}); }
}

// Minimal controller that is a contract (so Address.isContract passes) and reports owner for coordinator 0 as test caller
contract MinimalController {
    address deployer;
    constructor(address _deployer) { deployer = _deployer; }
    function isProduct(C) external pure returns (bool) { return false; }
    function owner(uint256) external view returns (address) { return deployer; }
    function coordinatorFor(IProduct) external pure returns (uint256) { return 0; }
    function collateral() external view returns (ICollateral) { return ICOLLATERAL_PLACEHOLDER(); }
    function incentivizer() external view returns (IIncentivizer) { return IINCENTIVIZER_PLACEHOLDER(); }
    function minFundingFee() external pure returns (UFixed18) { return UFixed18.wrap(0); }
    function paused() external pure returns (bool) { return false; }
}

